INSERT INTO `oc_product_description` (`product_id`, `language_id`, `name`, `description`, `tag`, `meta_title`, `meta_description`, `meta_keyword`) VALUES
(78, 1, 'Bezel Set Diamond Necklace', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;text-align: justify; width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;mso-height-source:userset;height:75.0pt&quot;&gt;\n  &lt;td height=&quot;100&quot; class=&quot;xl65&quot; width=&quot;338&quot; style=&quot;height:75.0pt;width:254pt&quot;&gt;Crafted\n  in 18K &amp;amp; 14K&amp;nbsp; gold and bezel set round natural Diamond. A simple and evergreen\n  design. This piece can be customized in all gold colors, purity and gemstone also.&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', 'Bezel Set Diamond Necklace', '', ''),
(80, 1, 'Diamond Oval Dot Dash Bracelet', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;text-align: justify; width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;mso-height-source:userset;height:75.0pt&quot;&gt;\n  &lt;td height=&quot;100&quot; class=&quot;xl65&quot; width=&quot;338&quot; style=&quot;height:75.0pt;width:254pt&quot;&gt;An\n  elegant diamond oval dot-dash bracelet has been designed in 18k gold and full cut white diamonds in micro pave setting. It can be customized in all gold colors and purity.&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', 'Diamond Oval Dot Dash Bracelet', '', ''),
(82, 1, 'Pave Set Forever Square Link Diamond Bracelet', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;text-align: justify; width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;mso-height-source:userset;height:75.0pt&quot;&gt;\n  &lt;td height=&quot;100&quot; class=&quot;xl65&quot; width=&quot;338&quot; style=&quot;text-align: justify; height: 75pt; width: 254pt;&quot;&gt;This\n  forever square link bracelet has been designed in 18K gold with VS\n  clarity white diamonds in full cut. It can also be made available in other metal colors and gold purity.&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', 'Pave Set Forever Square Link Diamond Bracelet', '', ''),
(84, 1, 'Geometric Link Diamond Bracelet', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;text-align: justify; width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;mso-height-source:userset;height:75.0pt&quot;&gt;\n  &lt;td height=&quot;100&quot; class=&quot;xl65&quot; width=&quot;338&quot; style=&quot;height:75.0pt;width:254pt&quot;&gt;This Micro Pave Set Charming diamond-adorned geometric link bracelet in 18K gold is stylish. It can also be customized in other gold colors and purity.&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', 'Geometric Link Diamond Bracelet', '', ''),
(85, 1, 'Diamond Circular Link Bracelet', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;text-align: justify; width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;mso-height-source:userset;height:75.0pt&quot;&gt;\n  &lt;td height=&quot;100&quot; class=&quot;xl65&quot; width=&quot;338&quot; style=&quot;text-align: justify; height: 75pt; width: 254pt;&quot;&gt;Emanating\n  bright sparkle this circular link bracelet dazzles with 18K gold and\n  petite diamonds in pave setting. This bracelet can be customized in all gold\n  colors and purity. It is available in SI clarity diamonds.&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', 'Diamond Circular Link Bracelet', '', ''),
(87, 1, 'White Diamond Oval Hoop Earrings', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;text-align: justify; width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;mso-height-source:userset;height:75.0pt&quot;&gt;\n  &lt;td height=&quot;100&quot; class=&quot;xl65&quot; width=&quot;338&quot; style=&quot;height:75.0pt;width:254pt&quot;&gt;Stunning\n  oval hoop earrings with two outer rows of diamonds in pave setting and the\n  central row in channel setting are designed in 18K gold. This product\n  can be tailor-made in other metal colors and gold purity.&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', 'White Diamond Oval Hoop Earrings', '', ''),
(89, 1, 'White and Brown Diamond Oval Hoop Earrings', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;text-align: justify; width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;mso-height-source:userset;height:75.0pt&quot;&gt;\n  &lt;td height=&quot;100&quot; class=&quot;xl65&quot; width=&quot;338&quot; style=&quot;height:75.0pt;width:254pt&quot;&gt;Stunning\n  oval hoop earrings with two outer rows of diamonds in pave setting and the\n  central row in channel setting are designed in 18K gold. This product\n  can be tailor-made in other metal colors and gold purity.&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', 'White and Brown Diamond Oval Hoop Earrings', '', ''),
(92, 1, 'Stunning Diamond and Tsavorite Watch', '', '', 'Stunning Diamond and Tsavorite Watch', '', ''),
(93, 1, 'Colourful Oblong Sapphire and Diamond Wrist watch', '', '', 'Colourful Oblong Sapphire and Diamond Wrist watch', '', ''),
(94, 1, 'Blue Sapphire and Diamond Oblong Wrist Watch', '', '', 'Blue Sapphire and Diamond Oblong Wrist Watch', '', ''),
(95, 1, 'Pretty Pink Sapphire and Diamond Watch', '', '', 'Pretty Pink Sapphire and Diamond Watch', '', ''),
(96, 1, 'Diamond Eternity Hoops', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;height: 75pt;&quot;&gt;&lt;td height=&quot;100&quot; class=&quot;xl65&quot; width=&quot;338&quot; style=&quot;height: 75pt; width: 254pt;&quot;&gt;House of Zayn Jewels presents a pair of hoops featuring 18k gold and single cut diamonds in micro pave setting. It comes with nicely secure and comfortable hinged snapbacks.&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', 'Diamond Eternity Hoops', '', ''),
(97, 1, 'Red Orange Sapphire and Diamond Round Watch', '', '', 'Red Orange Sapphire and Diamond Round Watch', '', ''),
(98, 1, 'Exquisite Yellow Sapphire and Diamond Watch', '', '', 'Exquisite Yellow Sapphire and Diamond Watch', '', ''),
(99, 1, 'Diamond Hoop Earrings', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;text-align: justify; width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;mso-height-source:userset;height:75.0pt&quot;&gt;\n  &lt;td height=&quot;100&quot; class=&quot;xl65&quot; width=&quot;338&quot; style=&quot;height:75.0pt;width:254pt&quot;&gt;This\n  chic pair is half covered with diamonds in micro pave setting in 18k gold and secured with nicely comfortable hinged snap backs. It can be\n  customized in all gold colors and purity.&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', 'Diamond Hoop Earrings', '', ''),
(100, 1, 'Striking Blue Sapphire and Diamond watch', '', '', 'Striking Blue Sapphire and Diamond watch', '', ''),
(101, 1, 'Novel Ruby, Sapphire and Diamond Oblong Wrist Watch', '', '', 'Novel Ruby, Sapphire and Diamond Oblong Wrist Watch', '', ''),
(102, 1, 'Brown Diamond Hoop Earrings', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;text-align: justify; width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;mso-height-source:userset;height:75.0pt&quot;&gt;\n  &lt;td height=&quot;100&quot; class=&quot;xl65&quot; width=&quot;338&quot; style=&quot;height:75.0pt;width:254pt&quot;&gt;This\n  chic pair is crafted with brown diamonds in micro pave setting and 18k gold. It also features secure and comfortable hinged snapbacks. It can be\n  customized as per customer requirement.&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', 'Brown Diamond Hoop Earrings', '', ''),
