(312, 1, 'Drop Diamond Floral Earrings', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;text-align: justify; width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;mso-height-source:userset;height:75.0pt&quot;&gt;\n  &lt;td height=&quot;100&quot; class=&quot;xl63&quot; width=&quot;338&quot; style=&quot;height:75.0pt;width:254pt&quot;&gt;This\n  eye-catching pair of earrings feature a floral design and is adorned with two\n  bezel diamonds attached with an 18k white gold chain. It can be customized in\n  14k white gold.&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', 'Drop Diamond Floral Earrings', '', ''),
(313, 1, 'Diamond Adorned Floral Necklace', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;text-align: justify; width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;mso-height-source:userset;height:75.0pt&quot;&gt;\n  &lt;td height=&quot;100&quot; class=&quot;xl65&quot; width=&quot;338&quot; style=&quot;height:75.0pt;width:254pt&quot;&gt;This\n  captivating 18k white gold chain necklace features a floral pendant clubbed\n  with a bezel diamond in center.&amp;nbsp; It can be customized as per\n  requirement.&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', 'Diamond Adorned Floral Necklace', '', ''),
(315, 1, 'Trio Triangle Stud Earrings', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;text-align: justify; width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;mso-height-source:userset;height:75.0pt&quot;&gt;\n  &lt;td height=&quot;100&quot; class=&quot;xl65&quot; width=&quot;338&quot; style=&quot;height:75.0pt;width:254pt&quot;&gt;A style\n  with incredible staying power. You cannot go wrong with trio triangle stud\n  earrings They are comfortable to wear and are made with 18k gold and VS diamonds. They can be customized to your choice of metal color\n  and metal purity.&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', ' Trio Triangle Stud Earrings', '', ''),
(317, 1, 'White Gold Round Earrings', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;text-align: justify; width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;mso-height-source:userset;height:75.0pt&quot;&gt;\n  &lt;td height=&quot;100&quot; class=&quot;xl65&quot; width=&quot;338&quot; style=&quot;height:75.0pt;width:254pt&quot;&gt;A chic\n  pair of Earrings featuring round diamonds in channel and micro pave setting along with 18k white gold. It can be customized in all gold colors and\n  purity.&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', 'White Gold Round Earrings', '', ''),
(318, 1, 'Trinity Knot Earrings', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;text-align: justify; width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;mso-height-source:userset;height:75.0pt&quot;&gt;\n  &lt;td height=&quot;100&quot; class=&quot;xl65&quot; width=&quot;338&quot; style=&quot;height:75.0pt;width:254pt&quot;&gt;The\n  three knots defines love, friendship and honesty.&amp;nbsp; Interlaced rose,\n  white and yellow 18k gold strands are a true testament of life. Made with\n  omega clip backs for a perfect fit. They can be customized in all gold\n  colors.&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', 'Trinity Knot Earrings', '', ''),
(319, 1, 'Channel set Diamond Pendant', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;text-align: justify; width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;mso-height-source:userset;height:75.0pt&quot;&gt;\n  &lt;td height=&quot;100&quot; class=&quot;xl63&quot; width=&quot;338&quot; style=&quot;height:75.0pt;width:254pt&quot;&gt;An\n  exquisite 18k white gold pendant with diamonds in channel and micro pave\n  settings. It can be customized in any metal color or purity.&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', 'Channel set Diamond Pendant', '', '');
INSERT INTO `oc_product_description` (`product_id`, `language_id`, `name`, `description`, `tag`, `meta_title`, `meta_description`, `meta_keyword`) VALUES
(320, 1, 'Key Diamond Pendant', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;text-align: justify; width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;mso-height-source:userset;height:75.0pt&quot;&gt;\n  &lt;td height=&quot;100&quot; class=&quot;xl65&quot; width=&quot;338&quot; style=&quot;height:75.0pt;width:254pt&quot;&gt;This\n  gorgeous diamond and white gold&amp;nbsp; key is set with round brilliant\n  diamonds in pave setting. Made in 18k gold and fine diamonds, it is an\n  excellent piece for in-house store collection. It can be customized in all\n  gold colors and purity.&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', 'Key Diamond Pendant', '', ''),
(321, 1, 'Circle and Drop Diamond Pendant', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;text-align: justify; width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;mso-height-source:userset;height:75.0pt&quot;&gt;\n  &lt;td height=&quot;100&quot; class=&quot;xl65&quot; width=&quot;338&quot; style=&quot;height:75.0pt;width:254pt&quot;&gt;This\n  delicate, contemporary pendant features a circle and a drop petal with full\n  cut, VS clarity diamonds designed in 18k white gold. Also available in yellow\n  gold.&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', 'Circle and Drop Diamond Pendant', '', ''),
(326, 1, 'Pebble Lariat and Drop Diamond Earrings', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;text-align: justify; width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;mso-height-source:userset;height:75.0pt&quot;&gt;\n  &lt;td height=&quot;100&quot; class=&quot;xl65&quot; width=&quot;338&quot; style=&quot;height:75.0pt;width:254pt&quot;&gt;You\n  cannot go wrong with these lariat earrings in 18k white gold. A single round\n  diamond in bezel setting is stationed at the end of a gold link chain make\n  for a flirty pair of earrings. It can be customized in all gold colors and\n  purity.&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', 'Pebble Lariat and Drop Diamond Earrings', '', ''),
(327, 1, 'Lariat Bezel Diamond Necklace', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;text-align: justify; width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;mso-height-source:userset;height:75.0pt&quot;&gt;\n  &lt;td height=&quot;100&quot; class=&quot;xl65&quot; width=&quot;338&quot; style=&quot;height:75.0pt;width:254pt&quot;&gt;Lariat\n  style necklace featuring mini bezel set diamonds. Crafted in 18k gold and\n  fine diamonds. Available in all gold colors and 14k gold purity.&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', 'Lariat Bezel Diamond Necklace', '', ''),
(329, 1, 'Square Line Diamond Eternity Ring', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;text-align: justify; width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;mso-height-source:userset;height:75.0pt&quot;&gt;\n  &lt;td height=&quot;100&quot; class=&quot;xl65&quot; width=&quot;338&quot; style=&quot;height:75.0pt;width:254pt&quot;&gt;Trendy\n  and pretty, this eternity ring is customized in 18k white gold and VS clarity\n  diamonds. It can be customized in all gold colors and purity.&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', 'Square Line Diamond Eternity Ring', '', ''),
(333, 1, 'Spiral Caterpillar Diamond Dangler Earrings', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;text-align: justify; width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;mso-height-source:userset;height:75.0pt&quot;&gt;\n  &lt;td height=&quot;100&quot; class=&quot;xl63&quot; width=&quot;338&quot; style=&quot;height:75.0pt;width:254pt&quot;&gt;Spiral\n  dangler earrings are as intriguing as the universe that we live in. Drawing\n  inspiration from our galaxy this piece epitomizes relaxed luxury. VS clarity\n  white diamonds have been beautifully used in pave setting to enhance the\n  spiral earrings. Crafted in 18k yellow gold these earrings can be customized\n  in all gold colors and purity.&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', 'Spiral Caterpillar Diamond Dangler Earrings', '', ''),
(334, 1, 'Spiral White Diamond Button Earrings', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;text-align: justify; width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;mso-height-source:userset;height:75.0pt&quot;&gt;\n  &lt;td height=&quot;100&quot; class=&quot;xl65&quot; width=&quot;338&quot; style=&quot;height:75.0pt;width:254pt&quot;&gt;Spiral\n  button earrings are as intriguing as the universe that we live in. Drawing\n  inspiration from our galaxy this piece epitomizes relaxed luxury. VS clarity\n  white diamonds have been beautifully used in pave setting to enhance the\n  spiral earrings. Crafted in 18k yellow gold these earrings can be customized\n  in all gold colors and purity.&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', 'Spiral White Diamond Button Earrings', '', ''),
(335, 1, 'Spiral Caterpillar Brown Diamond Earrings', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;text-align: justify; width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;mso-height-source:userset;height:75.0pt&quot;&gt;\n  &lt;td height=&quot;100&quot; class=&quot;xl65&quot; width=&quot;338&quot; style=&quot;height:75.0pt;width:254pt&quot;&gt;Spiral\n  caterpillar brown diamond earrings crafted in 18k yellow gold are elegant and\n  can be easily worn from morning to night. It can be customized in any gold\n  color and purity.&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', 'Spiral Caterpillar Brown Diamond Earrings', '', ''),
(337, 1, 'Jasmine Leaf Drop Diamond Earrings In White Diamond And Gold', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;text-align: justify; width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;mso-height-source:userset;height:75.0pt&quot;&gt;\n  &lt;td height=&quot;100&quot; class=&quot;xl65&quot; width=&quot;338&quot; style=&quot;height:75.0pt;width:254pt&quot;&gt;A\n  shimmering statement in diamond and gold. These earrings are fashioned in 18k\n  yellow gold and VS clarity diamonds. They can be customized to suit your\n  requirements.&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', 'Jasmine Leaf Drop Diamond Earrings In White Diamond And Gold', '', ''),
(338, 1, 'Jasmine Leaf Drop Earrings In Brown And White Diamonds', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;text-align: justify; width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;mso-height-source:userset;height:75.0pt&quot;&gt;\n  &lt;td height=&quot;100&quot; class=&quot;xl65&quot; width=&quot;338&quot; style=&quot;height:75.0pt;width:254pt&quot;&gt;A\n  shimmering statement in diamond and gold. These earrings are fashioned in 18k\n  yellow gold and diamonds. They can be customized to suit your requirements&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', 'Jasmine Leaf Drop Earrings In Brown And White Diamonds', '', ''),
(339, 1, 'Jasmine Leaf Drop Diamond Pendant In White Diamond And Gold', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;text-align: justify; width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;mso-height-source:userset;height:75.0pt&quot;&gt;\n  &lt;td height=&quot;100&quot; class=&quot;xl65&quot; width=&quot;338&quot; style=&quot;height:75.0pt;width:254pt&quot;&gt;A\n  shimmering statement in diamond and gold. This pendant is fashioned in 18k\n  yellow gold and VS clarity diamonds. It can be customized to suit your\n  requirements.&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', 'Jasmine Leaf Drop Diamond Pendant In White Diamond And Gold', '', ''),
(340, 1, 'Jasmine Leaf Drop Pendant In Brown And White Diamonds', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;text-align: justify; width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;mso-height-source:userset;height:75.0pt&quot;&gt;\n  &lt;td height=&quot;100&quot; class=&quot;xl65&quot; width=&quot;338&quot; style=&quot;height:75.0pt;width:254pt&quot;&gt;A\n  shimmering statement in diamond and gold. This pendant is fashioned in 18k\n  yellow gold and VS clarity diamonds. It can be customized to suit your\n  requirements.&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', 'Jasmine Leaf Drop Pendant In Brown And White Diamonds', '', ''),
(341, 1, 'Square White and Yellow Diamond Studs', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;text-align: justify; width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;mso-height-source:userset;height:75.0pt&quot;&gt;\n  &lt;td height=&quot;100&quot; class=&quot;xl63&quot; width=&quot;338&quot; style=&quot;height:75.0pt;width:254pt&quot;&gt;These\n  studs belong to signature collection. White diamond halo surrounds the yellow\n  diamonds, hand set in center in micro pave setting. This enduring style will\n  never fade and&amp;nbsp; can be worn forever. They have been crafted in 18k white\n  gold and can be customized in all gold colors and purity.&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', 'Square White and Yellow Diamond Studs', '', ''),
(344, 1, 'Classic Diamond Halo Stud Earrings', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;text-align: justify; width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;mso-height-source:userset;height:75.0pt&quot;&gt;\n  &lt;td height=&quot;100&quot; class=&quot;xl65&quot; width=&quot;338&quot; style=&quot;height:75.0pt;width:254pt&quot;&gt;These\n  dainty, elegant stud earrings are perfect for every day wear. They have been\n  beautifully crafted into a round halo design with VS clarity diamonds and 18k white gold. They can be customized in all gold colors and purity.&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', 'Classic Diamond Halo Stud Earrings', '', ''),
(345, 1, 'Classic Gold and Diamond Halo Ring', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;text-align: justify; width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;mso-height-source:userset;height:75.0pt&quot;&gt;\n  &lt;td height=&quot;100&quot; class=&quot;xl65&quot; width=&quot;338&quot; style=&quot;height:75.0pt;width:254pt&quot;&gt;Stunning\n  gold and diamond halo ring, that is truly timeless. This exquisite piece has\n  been crafted in 18k white gold and&amp;nbsp; VS clarity diamonds. It can be\n  customized&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', 'Classic Gold and Diamond Halo Ring', '', ''),
(346, 1, 'Classic Gold and Diamond Halo Ring', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;text-align: justify; width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;mso-height-source:userset;height:75.0pt&quot;&gt;\n  &lt;td height=&quot;100&quot; class=&quot;xl65&quot; width=&quot;338&quot; style=&quot;height:75.0pt;width:254pt&quot;&gt;Stunning\n  gold and diamond halo ring, that is truly timeless. This exquisite piece has\n  been crafted in 18k yellow gold and&amp;nbsp; VS clarity diamonds. It can be\n  customized&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', 'Classic Gold and Diamond Halo Ring', '', ''),
(347, 1, 'Mini Four Bezel Diamond Studs', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;mso-height-source:userset;height:75.0pt&quot;&gt;\n  &lt;td height=&quot;100&quot; class=&quot;xl65&quot; width=&quot;338&quot; style=&quot;height:75.0pt;width:254pt&quot;&gt;Simple\n  and dainty pair of earrings made in 18k white gold and mini bezel set\n  diamonds. Available in all gold colors and can be customized in 14k gold\n  purity too.&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', 'Mini Four Bezel Diamond Studs', '', ''),
(348, 1, 'Mini Four Bezel Diamond Necklace', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;text-align: justify; width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;mso-height-source:userset;height:75.0pt&quot;&gt;\n  &lt;td height=&quot;100&quot; class=&quot;xl65&quot; width=&quot;338&quot; style=&quot;height:75.0pt;width:254pt&quot;&gt;Simple\n  and dainty 18k white gold necklace with four diamonds in bezel setting. Can\n  be worn as a layered necklace. Available in all metal colors and 14k gold\n  purity too.&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', 'Mini Four Bezel Diamond Necklace', '', ''),
(350, 1, 'Gold and Diamond Halo Necklace', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;mso-height-source:userset;height:75.0pt&quot;&gt;\n  &lt;td height=&quot;100&quot; class=&quot;xl65&quot; width=&quot;338&quot; style=&quot;height:75.0pt;width:254pt&quot;&gt;Beautifully\n  designed halo necklace with five sparkling diamonds surrounded by petite\n  diamonds to make you feel special and to add captivating moments in your\n  everyday looks. This minimalist necklace is effortless style. It can be\n  customized in all gold colors and purity.&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', 'Gold and Diamond Halo Necklace', '', ''),
(352, 1, 'Halo Pear Earrings', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;text-align: justify; width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;mso-height-source:userset;height:75.0pt&quot;&gt;\n  &lt;td height=&quot;100&quot; class=&quot;xl63&quot; width=&quot;338&quot; style=&quot;height:75.0pt;width:254pt&quot;&gt;Simple\n  halo pear shaped studs are great for everyday. It is a classic pieces for all\n  occasions whether an office day, holiday party or just a day at home. They\n  are comfortable to wear made in 18k white gold and colorless VS clarity and\n  full cut diamonds.&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', ' Halo Pear Earrings', '', ''),
(353, 1, 'Bezel Drop by the Yard Earrings', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;text-align: justify; width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;mso-height-source:userset;height:75.0pt&quot;&gt;\n  &lt;td height=&quot;100&quot; class=&quot;xl65&quot; width=&quot;338&quot; style=&quot;height:75.0pt;width:254pt&quot;&gt;Simple\n  and sleek, these earrings are designed in a single line with five stations.\n  18k white gold and VS clarity diamonds have been used to craft these\n  incredible earrings. They can be customized as per specification.&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', 'Bezel Drop by the Yard Earrings', '', ''),
(355, 1, 'Classic Diamond by Yard Necklace', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;text-align: justify; width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;mso-height-source:userset;height:75.0pt&quot;&gt;\n  &lt;td height=&quot;100&quot; class=&quot;xl63&quot; width=&quot;338&quot; style=&quot;height:75.0pt;width:254pt&quot;&gt;An\n  evergreen design made in 18k white gold and fine diamonds. Available in all\n  gold colors and can be customized in 14k gold purity.&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', 'Classic Diamond by Yard Necklace', '', ''),
(358, 1, 'Midi Drop Earrings', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;text-align: justify; width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;mso-height-source:userset;height:75.0pt&quot;&gt;\n  &lt;td height=&quot;100&quot; class=&quot;xl63&quot; width=&quot;338&quot; style=&quot;height:75.0pt;width:254pt&quot;&gt;Midi\n  bezel set drop earrings in 18k white gold and fine diamonds. Available in all\n  metal colors and 14k gold purity.&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', 'Midi Drop Earrings', '', ''),
(360, 1, 'Dancing Diamonds Layered Necklace', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;text-align: justify; width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;mso-height-source:userset;height:75.0pt&quot;&gt;\n  &lt;td height=&quot;100&quot; class=&quot;xl65&quot; width=&quot;338&quot; style=&quot;height:75.0pt;width:254pt&quot;&gt;Elegant\n  in simplicity , this diamond and white gold layered necklace has been set in\n  18k gold and fine diamonds. Dancing diamonds have been stationed at\n  regular interval. Available in all gold colors and 14k gold purity.&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', 'Dancing Diamonds Layered Necklace', '', ''),
(361, 1, 'Bezel Drop Diamond Earrings', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;text-align: justify; width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;mso-height-source:userset;height:75.0pt&quot;&gt;\n  &lt;td height=&quot;100&quot; class=&quot;xl65&quot; width=&quot;338&quot; style=&quot;height:75.0pt;width:254pt&quot;&gt;These\n  bezel drop diamond earrings on a single chain is effortless style. This\n  minimalist jewelry&amp;nbsp;is simple and easy to wear. It can be customized in\n  all gold colors and purity.&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', 'Bezel Drop Diamond Earrings', '', ''),
(369, 1, 'Elegant Diamond Cross Pendant', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;text-align: justify; width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;mso-height-source:userset;height:75.0pt&quot;&gt;\n  &lt;td height=&quot;100&quot; class=&quot;xl63&quot; width=&quot;338&quot; style=&quot;height:75.0pt;width:254pt&quot;&gt;This\n  splendid gold and diamond cross pendant is crafted with 18k white gold and\n  diamonds. It can be customized in all gold colors and purity.&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', 'Elegant Diamond Cross Pendant', '', ''),
(370, 1, 'Simplicity Diamond Pear Shaped Pendant', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;text-align: justify; width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;mso-height-source:userset;height:75.0pt&quot;&gt;\n  &lt;td height=&quot;100&quot; class=&quot;xl65&quot; width=&quot;338&quot; style=&quot;height:75.0pt;width:254pt&quot;&gt;This\n  classic gold drop style pendant feature twin graduated size open tear drops\n  paved with petite diamonds in yellow gold. It can be customized in all metal\n  colors and gold purity.&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', 'Simplicity Diamond Pear Shaped Pendant', '', ''),
(371, 1, 'Round Chandelier Drop Diamond Necklace', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;text-align: justify; width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;mso-height-source:userset;height:75.0pt&quot;&gt;\n  &lt;td height=&quot;100&quot; class=&quot;xl63&quot; width=&quot;338&quot; style=&quot;height:75.0pt;width:254pt&quot;&gt;Simply\n  superb round chandelier drop diamond necklace with marquise cut emerald is\n  wonderful. This can also be customized in 14k gold purity too.&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', 'Round Chandelier Drop Diamond Necklace', '', ''),
(372, 1, 'Chandelier Drop Diamond and Emerald Earrings', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;text-align: justify; width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;mso-height-source:userset;height:75.0pt&quot;&gt;\n  &lt;td height=&quot;100&quot; class=&quot;xl65&quot; width=&quot;338&quot; style=&quot;height:75.0pt;width:254pt&quot;&gt;18k\n  White Gold round chandelier drop diamond hoop earrings with Marquise Cut\n  Emerald are captivating. They can be customized in 14k gold purity too.&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', 'Chandelier Drop Diamond and Emerald Earrings', '', ''),
(373, 1, 'Floral Tiara Diamond Ring', '&lt;p style=&quot;text-align: justify;&quot;&gt;Delicate and dainty this ring with a diamond-studded tiara on the head is alluring. It has been fashioned in 18k white gold and diamonds. It can be customized in all gold colors, purity and ring sizes.&lt;/p&gt;&lt;div style=&quot;text-align: justify;&quot;&gt;&lt;br&gt;&lt;/div&gt;', '', 'Floral Tiara Diamond Ring', '', ''),
(374, 1, 'Floral Tiara Diamond Ring', '&lt;p style=&quot;text-align: justify; &quot;&gt;Delicate and dainty this ring with a diamond-studded tiara on the head is alluring. It has been fashioned in 18k yellow gold and diamonds. It can be customized in all gold colors, purity and ring sizes.&lt;/p&gt;&lt;div style=&quot;text-align: justify;&quot;&gt;&lt;br&gt;&lt;/div&gt;', '', 'Floral Tiara Diamond Ring', '', ''),
(375, 1, 'Interlocking Mini White Diamond Pendant', '&lt;p style=&quot;text-align: justify;&quot;&gt;This lovable pendant is crafted in 18k white gold and diamonds. It can be fashioned in all gold colors and purity. Also available in SI clarity diamonds.&lt;/p&gt;&lt;div&gt;&lt;br&gt;&lt;/div&gt;', '', 'Interlocking Mini White Diamond Pendant', '', ''),
(376, 1, 'Interlocking Mini White Diamond Earring', '&lt;p style=&quot;text-align: justify;&quot;&gt;These lovable earrings are crafted in 18k white gold and diamonds. They can be fashioned in all gold colors and purity. Also available in SI clarity diamonds.&lt;/p&gt;&lt;div&gt;&lt;br&gt;&lt;/div&gt;', '', 'Interlocking Mini White Diamond Earring', '', ''),
(377, 1, 'Floral Square Diamond Earring', '&lt;p style=&quot;text-align: justify; &quot;&gt;These square diamond earring in 18k white gold and diamonds with a flower in the center is feminine and stylish. This earring can also be made available in all gold colors and purity.&lt;/p&gt;&lt;div&gt;&lt;br&gt;&lt;/div&gt;', '', 'Floral Square Diamond Earring', '', ''),
(378, 1, 'Floral Square Diamond Pendant', '&lt;p&gt;These square diamond pendant in 18k white gold and diamonds with a flower in the center is feminine and stylish. This pendant can also be made available in all gold colors and purity.&lt;/p&gt;&lt;div&gt;&lt;br&gt;&lt;/div&gt;', '', 'Floral Square Diamond Pendant', '', ''),
(379, 1, 'Victoria Diamond Eternity Ring', '&lt;p style=&quot;text-align: justify;&quot;&gt;This diamond zigzag, eternity ring features round diamonds in 18k yellow gold. It can be customized in all gold colors and purity.&lt;/p&gt;&lt;div&gt;&lt;br&gt;&lt;/div&gt;', '', 'Victoria Diamond Eternity Ring', '', ''),
(380, 1, 'Victoria Diamond Eternity Ring', '&lt;p style=&quot;text-align: justify;&quot;&gt;This diamond zigzag, eternity ring features round diamonds in 18k white gold. It can be customized in all gold colors and purity.&lt;/p&gt;&lt;div&gt;&lt;br&gt;&lt;/div&gt;', '', 'Victoria Diamond Eternity Ring', '', ''),
(381, 1, 'Victoria Diamond Pendant', '&lt;p align=&quot;justify&quot;&gt;This linear wave pendant has been crafted in 18k white gold and VS clarity diamonds. Its simple yet stylish craftsmanship is attractive. This pendant can be customized in all gold colors and purity.&lt;/p&gt;&lt;div&gt;&lt;br&gt;&lt;/div&gt;', '', 'Victoria Diamond Pendant', '', ''),
(382, 1, 'Square Diamond Cushion Pendant', '&lt;p style=&quot;text-align: justify; &quot;&gt;These charming square cushion diamond pendant feature VS clarity diamonds in 18k white gold. These earrings can be customized in all gold colors and purity.&lt;/p&gt;&lt;div&gt;&lt;br&gt;&lt;/div&gt;', '', 'Square Diamond Cushion Pendant', '', ''),
(383, 1, 'Square Diamond Cushion Earring', '&lt;p style=&quot;text-align: justify; &quot;&gt;These charming square cushion diamond earrings feature VS clarity diamonds in 18k white gold. These earrings can be customized in all gold colors and purity.&lt;/p&gt;&lt;div&gt;&lt;br&gt;&lt;/div&gt;', '', 'Square Diamond Cushion Earring', '', ''),
(384, 1, 'Milgrain Dot Diamond and Gold Ring', '&lt;p style=&quot;text-align: justify; &quot;&gt;This dot diamond ring has been fashioned in 18k white gold. Round diamonds have been encased in gold with milgrain detailing on the edges. This ring can be customized in all gold colors, purity and sizes.&lt;/p&gt;&lt;div style=&quot;text-align: justify;&quot;&gt;&lt;br&gt;&lt;/div&gt;', '', 'Milgrain Dot Diamond and Gold Ring', '', ''),
(385, 1, 'Milgrain Dot Diamond and Gold Ring', '&lt;p style=&quot;text-align: justify;&quot;&gt;This dot diamond ring has been fashioned in 18k yellow gold. Round diamonds have been encased in gold with milgrain detailing on the edges. This ring can be customized in all gold colors, purity, and sizes.&lt;/p&gt;&lt;div style=&quot;text-align: justify;&quot;&gt;&lt;br&gt;&lt;/div&gt;', '', 'Milgrain Dot Diamond and Gold Ring', '', ''),
(386, 1, 'Milgrain Dot Diamond and Gold Ring', '&lt;p style=&quot;text-align: justify;&quot;&gt;This dot diamond ring has been fashioned in 18k rose gold. Round diamonds have been encased in gold with milgrain detailing on the edges. This ring can be customized in all gold colors, purity, and sizes.&lt;/p&gt;&lt;div style=&quot;text-align: justify;&quot;&gt;&lt;br&gt;&lt;/div&gt;', '', 'Milgrain Dot Diamond and Gold Ring', '', ''),
(387, 1, 'Geometric White Diamond Pendant', '&lt;p style=&quot;text-align: justify;&quot;&gt;This geometric design pendant with circle, square, and triangle is a sure-shot trailblazer. It has been crafted in 18k white gold and diamonds. The triangle in the center is studded with diamonds whereas the circle and square are in plain white gold. This pendant can be customized as required.&lt;/p&gt;&lt;div style=&quot;text-align: justify;&quot;&gt;&lt;br&gt;&lt;/div&gt;', '', 'Geometric White Diamond Pendant', '', ''),
(388, 1, 'Geometric White Diamond Earrings', '&lt;p style=&quot;text-align: justify;&quot;&gt;These geometric design earrings with circle, square, and triangle are a sure shot trailblazer. They have been crafted in 18k white gold and diamonds. The triangle in the center is studded with diamonds whereas the circle and square are in plain white gold. These earrings can be customized as required.&lt;/p&gt;&lt;div&gt;&lt;br&gt;&lt;/div&gt;', '', 'Geometric White Diamond Earrings', '', ''),
(389, 1, 'Tear Drop Hoop Earrings', '&lt;p style=&quot;text-align: justify;&quot;&gt;These teardrop hoop earrings are crafted with 18k white gold and VS clarity diamonds. These earrings can be customized in all gold colors and purity.&lt;/p&gt;&lt;div&gt;&lt;br&gt;&lt;/div&gt;', '', 'Tear Drop Hoop Earrings', '', ''),
(390, 1, 'Full Moon Brown &amp; White Diamond Pendant', '&lt;p style=&quot;text-align: justify;&quot;&gt;A stylish Full Moon filigree pendant adorned with brown and white diamonds in 18-karat white gold is fresh and innovative. It can be customized in all metal colors and gold purity.&lt;/p&gt;&lt;div&gt;&lt;br&gt;&lt;/div&gt;', '', 'Full Moon Brown &amp; White Diamond Pendant', '', ''),
(391, 1, 'Ornamental Double Leaf Diamond and Gold Earrings', '&lt;p style=&quot;text-align: justify;&quot;&gt;These diamond and gold earrings will always lend a sparkle to your outfit. They have been created in 18k white gold and VS clarity diamonds. They can be customized as per your specifications.&lt;/p&gt;&lt;div style=&quot;text-align: justify;&quot;&gt;&lt;br&gt;&lt;/div&gt;', '', 'Ornamental Double Leaf Diamond and Gold Earrings', '', ''),
(392, 1, 'Triple Line Diamond Hoops', '&lt;p style=&quot;text-align: justify; &quot;&gt;Pair of 18k white gold hoops semi-covered with triple line of diamonds. This pair is available in all gold colors and 14k&amp;nbsp; metal purity. This can also be customized&amp;nbsp; SI and VS clarity diamonds.&lt;/p&gt;&lt;div&gt;&lt;br&gt;&lt;/div&gt;', '', 'Triple Line Diamond Hoops', '', ''),
(395, 1, 'Diamond and Gold Trellis Earrings', '&lt;p style=&quot;text-align: justify;&quot;&gt;Designed in 18k white gold and diamonds these huggee earrings are marvelous. They can be customized in all gold colors and purity.&lt;/p&gt;&lt;div style=&quot;text-align: justify;&quot;&gt;&lt;br&gt;&lt;/div&gt;', '', 'Diamond and Gold Trellis Earrings', '', ''),
(396, 1, 'Lattice Diamond Earrings', '&lt;p style=&quot;text-align: justify;&quot;&gt;A chic pair of round diamond and gold&amp;nbsp;Earrings with lattice design. They have been crafted in 18k white gold and diamonds.Two rows of diamonds border the lattice design in the center. These can be customized in all gold colors and purity.&lt;/p&gt;&lt;div style=&quot;text-align: justify;&quot;&gt;&lt;br&gt;&lt;/div&gt;', '', 'Lattice Diamond Earrings', '', ''),
(397, 1, 'Floating Diamond and Sapphire Earrings', '&lt;p style=&quot;text-align: justify; &quot;&gt;These exquisite stud earrings feature floating diamonds and blue sapphires in a circular ring. They can be customized in all gold colors and purity.&lt;/p&gt;&lt;div style=&quot;text-align: justify;&quot;&gt;&lt;br&gt;&lt;/div&gt;', '', 'Floating Diamond and Sapphire Earrings', '', ''),
(398, 1, 'Floating Diamond and Sapphire Necklace', '&lt;p&gt;Brilliantly crafted diamonds and blue sapphire emitting radiance. This necklace is a fine art made in 18k white gold. It can be customized in all gold colors and purity.&lt;/p&gt;&lt;div&gt;&lt;br&gt;&lt;/div&gt;', '', 'Floating Diamond and Sapphire Necklace', '', ''),
(400, 1, 'Elegant Chandelier Drop Necklace', '&lt;p style=&quot;text-align: justify; &quot;&gt;18k white gold brilliantly crafted chandelier drop necklace combined with marquise cut emerald and bezel set diamonds is unique. It can be made available in 14k gold purity too.&lt;/p&gt;&lt;div&gt;&lt;br&gt;&lt;/div&gt;', '', 'Elegant Chandelier Drop Necklace', '', ''),
(401, 1, 'Elegant Chandelier Drop Earring', '&lt;p style=&quot;text-align: justify;&quot;&gt;Fancy shaped drop earrings with natural emerald. Set in 18k gold and fine diamonds. Available in rose and yellow gold as well. Can be customized in 14k gold purity.&lt;/p&gt;&lt;div&gt;&lt;br&gt;&lt;/div&gt;', '', 'Elegant Chandelier Drop Earring', '', ''),
(402, 1, 'Elegant Emerald Necklace', '&lt;p style=&quot;text-align: justify;&quot;&gt;Beautiful marquise emerald necklace set with 18k white gold and diamonds. Specially crafted to add more charm to your looks. A jewel worth being owned. This necklace can be customized in all gold colors and purity.&lt;br&gt;&lt;/p&gt;', '', 'Elegant Emerald Necklace', '', ''),
(403, 1, 'Elegant Stud with Emerald', '&lt;p style=&quot;text-align: justify;&quot;&gt;Graceful Drop Earrings set in 18k white gold With Marquise Emerald. This dazzling pair of earrings gives a simple yet sophisticated look.&lt;br&gt;&lt;/p&gt;', '', 'Elegant Stud with Emerald', '', ''),
(404, 1, 'Classic Diamond Hoop Earrings', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;text-align: justify; width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;mso-height-source:userset;height:75.0pt&quot;&gt;\n  &lt;td height=&quot;100&quot; class=&quot;xl63&quot; width=&quot;338&quot; style=&quot;height:75.0pt;width:254pt&quot;&gt;Elegant\n  in simplicity, these 18K gold hoop earrings are studded with glistening\n  rows of diamonds in single cut. They can be customized in all gold colors and\n  purity.&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', 'Classic Diamond Hoop Earrings', '', ''),
(406, 1, 'Classic Brown Diamond Hoop Earrings', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;text-align: justify; width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;mso-height-source:userset;height:75.0pt&quot;&gt;\n  &lt;td height=&quot;100&quot; class=&quot;xl65&quot; width=&quot;338&quot; style=&quot;height:75.0pt;width:254pt&quot;&gt;Elegant\n  in simplicity, these 18K gold hoop earrings are studded with glistening\n  rows of brown diamonds in single cut. They can be customized in all gold\n  colors and purity.&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', 'Classic Brown Diamond Hoop Earrings', '', ''),
(409, 1, 'Classic Diamond Hoop Earrings', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;text-align: justify; width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;mso-height-source:userset;height:75.0pt&quot;&gt;\n  &lt;td height=&quot;100&quot; class=&quot;xl65&quot; width=&quot;338&quot; style=&quot;height:75.0pt;width:254pt&quot;&gt;These\n  18K gold&amp;nbsp; and diamond hoop\n  earrings are a great choice for simple styling. They can be customized in all\n  gold colors and purity&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', 'Classic Diamond Hoop Earrings', '', ''),
(412, 1, 'Classic Brown Diamond Hoop Earrings', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;text-align: justify; width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;mso-height-source:userset;height:75.0pt&quot;&gt;\n  &lt;td height=&quot;100&quot; class=&quot;xl65&quot; width=&quot;338&quot; style=&quot;height:75.0pt;width:254pt&quot;&gt;These\n  18K gold&amp;nbsp; and brown diamond hoop\n  earrings in single cut are a great choice for simple styling. They can be\n  customized in all gold colors and purity&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', 'Classic Brown Diamond Hoop Earrings', '', ''),
(416, 1, 'Classic Diamond Hoop Earrings', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;text-align: justify; width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;mso-height-source:userset;height:75.0pt&quot;&gt;\n  &lt;td height=&quot;100&quot; class=&quot;xl63&quot; width=&quot;338&quot; style=&quot;height:75.0pt;width:254pt&quot;&gt;This\n  pair of classic diamond hoop earrings crafted in 18K gold and fully\n  covered with diamonds in micro pave setting comes with comfortable hinged\n  snap-backs. It can also be customized in all metal colors and 14K gold purity.&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', 'Classic Diamond Hoop Earrings', '', ''),
(418, 1, 'Classic Brown Diamond Hoops', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;text-align: justify; width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;mso-height-source:userset;height:75.0pt&quot;&gt;\n  &lt;td height=&quot;100&quot; class=&quot;xl65&quot; width=&quot;338&quot; style=&quot;height:75.0pt;width:254pt&quot;&gt;This\n  chic pair of hoops is exquisitely crafted in 18K gold and single cut\n  brown diamonds in micro pave setting. It is also nicely secured with\n  comfortable hinged snap backs. It can be customized in all gold colors and\n  purity.&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', 'Classic Brown Diamond Hoops', '', ''),
(421, 1, 'Diamond Hoop Earrings', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;text-align: justify; width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;mso-height-source:userset;height:75.0pt&quot;&gt;\n  &lt;td height=&quot;100&quot; class=&quot;xl63&quot; width=&quot;338&quot; style=&quot;height:75.0pt;width:254pt&quot;&gt;Designed\n  in 18K gold and adorned with diamonds in micro pave setting. This pair\n  of hoops is for your day to day wear. It is also nicely secured with\n  comfortable hinged snap-backs.&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', 'Diamond Hoop Earrings', '', ''),
(424, 1, 'Triple Diamond Dot Studs', '&lt;p style=&quot;text-align: justify;&quot;&gt;Minimalist three dot earrings are incredibly versatile and best jewelry style to wear every single day. They have been crafted in 18k gold and VS clarity diamonds in bezel setting. They can be customized in all gold colors and purity.&lt;br&gt;&lt;/p&gt;', '', 'Triple Diamond Dot Studs', '', ''),
(425, 1, 'Emerald and Diamonds Studs', '&lt;p style=&quot;text-align: justify; &quot;&gt;18k White Gold Bezel Set Emerald studs surrounded halfway with diamonds. A design for many occasions. These earrings can be customized in all gold colors, purity and precious stones.&lt;br&gt;&lt;/p&gt;', '', 'Emerald and Diamonds Studs', '', ''),
(426, 1, 'Leaf and Hoop Diamond Dangle Earrings', '&lt;p style=&quot;text-align: justify;&quot;&gt;Artistically crafted this leaf and hoop earrings are charming. They have been crafted in 18k white gold and VS clarity full cut round brilliant diamonds. They can be customized in all gold colors and purity.&lt;br&gt;&lt;/p&gt;', '', 'Leaf and Hoop Diamond Dangle Earrings', '', ''),
(428, 1, 'Diamond Cushion Link Ring', '&lt;p style=&quot;text-align: justify; &quot;&gt;This stunning cushion link band has a sense of timelessness. Crafted in 18k gold and full-cut diamonds, it can be customized in all gold colors, purity, and ring sizes.&lt;br&gt;&lt;/p&gt;', '', 'Diamond Cushion Link Ring', '', ''),
(429, 1, 'Diamond Cushion Link Ring', '&lt;p&gt;This stunning cushion link band has a sense of timelessness. Crafted in 18k gold and full-cut diamonds, it can be customized in all gold colors, purity, and ring sizes.&lt;br&gt;&lt;/p&gt;', '', 'Diamond Cushion Link Ring', '', ''),
(430, 1, 'Crescent Moon Diamond Ring', '&lt;p style=&quot;text-align: justify;&quot;&gt;This simple plain band in white gold with crescent studded with diamond on the open end is pretty. It has been crafted in 18k white gold and VS clarity diamonds. It can be customized in all gold colors, purity and ring sizes.&lt;/p&gt;', '', 'Crescent Moon Diamond Ring', '', ''),
(431, 1, 'Crown Diamond Ring', '&lt;p style=&quot;text-align: justify;&quot;&gt;This simple plain band in white gold with a curved crest is pretty. It has been crafted in 18k white gold and VS clarity diamonds. It can be customized in all gold colors, purity and ring sizes.&lt;br&gt;&lt;/p&gt;', '', 'Crown Diamond Ring', '', ''),
(432, 1, 'Diamond Link Ring', '&lt;p style=&quot;text-align: justify;&quot;&gt;Shine in style with this oval-linked ring in 18k white gold. The links are studded with diamonds in micro pave setting to add sparkle. This ring can be customized in all gold colors, purity and ring sizes.&lt;br&gt;&lt;/p&gt;', '', 'Diamond Link Ring', '', ''),
(433, 1, 'Classic Brown Diamond Hoop Earrings', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;text-align: justify; width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;mso-height-source:userset;height:75.0pt&quot;&gt;\n  &lt;td height=&quot;100&quot; class=&quot;xl63&quot; width=&quot;338&quot; style=&quot;height:75.0pt;width:254pt&quot;&gt;This\n  fashionable pair of hoops is designed in 18K white gold and brown diamonds in\n  micro pave setting. It also features secure and comfortable hinged snap backs.&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', 'Classic Brown Diamond Hoop Earrings', '', ''),
(434, 1, 'Brown Diamond Eternity Hoops', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;text-align: justify; width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;mso-height-source:userset;height:75.0pt&quot;&gt;\n  &lt;td height=&quot;100&quot; class=&quot;xl65&quot; width=&quot;338&quot; style=&quot;height:75.0pt;width:254pt&quot;&gt;This\n  fashionable pair of hoops is designed in 18k rose gold and brown single cut\n  diamonds in micro pave setting. It is also nicely secured with comfortable\n  hinged snap backs. It can be customized in all gold colors and purity.&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', 'Brown Diamond Eternity Hoops', '', ''),
(435, 1, 'Fashionable Diamond And Gold Hoops', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;text-align: justify; width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;mso-height-source:userset;height:75.0pt&quot;&gt;\n  &lt;td height=&quot;100&quot; class=&quot;xl65&quot; width=&quot;338&quot; style=&quot;height:75.0pt;width:254pt&quot;&gt;An\n  exquisite pair of hoops designed in 18K gold and single cut diamonds in\n  micro pave setting. It also features secure and comfortable hinged snap backs.\n  It can be customized in all gold colors and purity.&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', 'Fashionable Diamond And Gold Hoops', '', ''),
(438, 1, 'Brown Diamonds And White Gold Hoops', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;text-align: justify; width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;mso-height-source:userset;height:75.0pt&quot;&gt;\n  &lt;td height=&quot;100&quot; class=&quot;xl65&quot; width=&quot;338&quot; style=&quot;height:75.0pt;width:254pt&quot;&gt;Simply\n  beautiful pair of hoop earrings is designed in 18K white gold and single cut\n  brown diamonds in micro pave setting . It can also be customized in 14K gold\n  purity.&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', 'Brown Diamonds And White Gold Hoops', '', ''),
(439, 1, 'Gold and Diamond Hoop Earrings', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;text-align: justify; width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;mso-height-source:userset;height:75.0pt&quot;&gt;\n  &lt;td height=&quot;100&quot; class=&quot;xl63&quot; width=&quot;338&quot; style=&quot;height:75.0pt;width:254pt&quot;&gt;This\n  pair of hoop earrings crafted in 18K gold and half covered with\n  diamonds in micro pave setting comes with comfortable hinged snap backs. It\n  can also be customized in 14K gold purity.&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', 'Gold and Diamond Hoop Earrings', '', ''),
(442, 1, 'Gold and Diamond Hoop Earrings', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;text-align: justify; width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;mso-height-source:userset;height:75.0pt&quot;&gt;\n  &lt;td height=&quot;100&quot; class=&quot;xl63&quot; width=&quot;338&quot; style=&quot;height:75.0pt;width:254pt&quot;&gt;This\n  pair of hoop earrings crafted in 18K gold and half covered with brown diamonds in micro pave setting comes with comfortable hinged snap backs. It\n  can also be customized in 14K gold purity.&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', 'Gold and Diamond Hoop Earrings', '', ''),
(443, 1, 'Classic Diamond Hoop Earrings', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;text-align: justify; width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;mso-height-source:userset;height:75.0pt&quot;&gt;\n  &lt;td height=&quot;100&quot; class=&quot;xl65&quot; width=&quot;338&quot; style=&quot;height:75.0pt;width:254pt&quot;&gt;Delicate\n  and beautiful, diamond hoop earrings have been crafted with 18K gold\n  and fine white diamonds in single cut. They can be customized in all gold colors and purity.&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', 'Classic Diamond Hoop Earrings', '', ''),
(445, 1, 'Classic Diamond Hoop Earrings', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;text-align: justify; width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;mso-height-source:userset;height:75.0pt&quot;&gt;\n  &lt;td height=&quot;100&quot; class=&quot;xl65&quot; width=&quot;338&quot; style=&quot;height:75.0pt;width:254pt&quot;&gt;Delicate\n  and beautiful, diamond hoop earrings have been crafted with 18k yellow gold\n  and fine brown diamonds in single cut. They can be customized in all gold colors and purity&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', 'Classic Diamond Hoop Earrings', '', ''),
(446, 1, 'Parallel Lines Diamond Ring', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;text-align: justify; width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;mso-height-source:userset;height:75.0pt&quot;&gt;\n  &lt;td height=&quot;100&quot; class=&quot;xl63&quot; width=&quot;338&quot; style=&quot;height:75.0pt;width:254pt&quot;&gt;This\n  simple parallel line ring with a diamond studded triangular head is\n  comfortable. It has been crafted in 18k white gold and diamonds. It can be\n  customized in all gold colors, purity and ring sizes.&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', 'Parallel Lines Diamond Ring', '', ''),
(447, 1, 'Mini Circle Diamond Stud', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;text-align: justify; width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;mso-height-source:userset;height:75.0pt&quot;&gt;\n  &lt;td height=&quot;100&quot; class=&quot;xl65&quot; width=&quot;338&quot; style=&quot;height:75.0pt;width:254pt&quot;&gt;Classic\n  and elegant pair of open stud&amp;nbsp; circular earrings featuring micro pave\n  diamonds in 18k white gold. Perfect for everyday wear.&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', 'Mini Circle Diamond Stud', '', ''),
(449, 1, 'Trio Circle Diamond and Gold Necklace', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;text-align: justify; width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;mso-height-source:userset;height:75.0pt&quot;&gt;\n  &lt;td height=&quot;100&quot; class=&quot;xl65&quot; width=&quot;338&quot; style=&quot;height:75.0pt;width:254pt&quot;&gt;This\n  modern and youthful necklace made with 18k white and yellow gold features\n  trio wheels of fine diamonds and yellow gold. This necklace can be customized\n  in all gold colors and purity.&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', 'Trio Circle Diamond and Gold Necklace', '', ''),
(450, 1, 'Rectangle Trellis Diamond Earrings', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;text-align: justify; width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;mso-height-source:userset;height:75.0pt&quot;&gt;\n  &lt;td height=&quot;100&quot; class=&quot;xl65&quot; width=&quot;338&quot; style=&quot;height:75.0pt;width:254pt&quot;&gt;Beautiful\n  trellis diamond and 18k gold earrings have been crafted with care and\n  aesthetics. These earrings can be customized in all gold colors and purity.&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', 'Rectangle Trellis Diamond Earrings', '', ''),
(451, 1, 'Aphrodite Diamond and Gold Oval Earrings', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;text-align: justify; width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;mso-height-source:userset;height:75.0pt&quot;&gt;\n  &lt;td height=&quot;100&quot; class=&quot;xl65&quot; width=&quot;338&quot; style=&quot;height:75.0pt;width:254pt&quot;&gt;Aphrodite\n  hoop earrings have been fashioned in 18k gold and full cut white diamonds in micro pave setting. Three graduated rings of white gold with center one studded with\n  diamonds make this piece fancy. It can be customized in all gold colors and\n  purity.&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', 'Aphrodite Diamond and Gold Oval Earrings', '', '');
INSERT INTO `oc_product_description` (`product_id`, `language_id`, `name`, `description`, `tag`, `meta_title`, `meta_description`, `meta_keyword`) VALUES
(453, 1, 'Fancy Diamond &amp; Gold Leaf Drop Earrings', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;text-align: justify; width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;mso-height-source:userset;height:75.0pt&quot;&gt;\n  &lt;td height=&quot;100&quot; class=&quot;xl65&quot; width=&quot;338&quot; style=&quot;height:75.0pt;width:254pt&quot;&gt;These\n  shimmering leaf drop earrings in 18k white gold and diamonds would add a touch\n  of class to any outfit. They can be customized in all gold colors and purity.&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', 'Fancy Diamond &amp; Gold Leaf Drop Earrings', '', ''),
(455, 1, 'Tear Drop Diamond &amp; Gold Earrings', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;text-align: justify; width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;mso-height-source:userset;height:75.0pt&quot;&gt;\n  &lt;td height=&quot;100&quot; class=&quot;xl65&quot; width=&quot;338&quot; style=&quot;height:75.0pt;width:254pt&quot;&gt;Open\n  tear drop earrings have been crafted in 18k white gold and full cut white\n  diamonds in pave setting. These earrings have been accentuated with a\n  beautiful scroll in gold in center. They can be customized in all gold\n  colors.&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', 'Tear Drop Diamond &amp; Gold Earrings', '', ''),
(457, 1, 'Diamond and Gold Hoop Earrings', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;text-align: justify; width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;mso-height-source:userset;height:75.0pt&quot;&gt;\n  &lt;td height=&quot;100&quot; class=&quot;xl63&quot; width=&quot;338&quot; style=&quot;height:75.0pt;width:254pt&quot;&gt;This\n  pair of hoops have been crafted in 18K gold and diamonds for the young\n  and stylish. Customization is available for all gold colors and purity.&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', 'Diamond and Gold Hoop Earrings', '', ''),
(460, 1, 'Brown Diamond and Gold Hoop Earrings', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;text-align: justify; width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;mso-height-source:userset;height:75.0pt&quot;&gt;\n  &lt;td height=&quot;100&quot; class=&quot;xl65&quot; width=&quot;338&quot; style=&quot;height:75.0pt;width:254pt&quot;&gt;This\n  beautiful pair of hoop earrings is designed with brown diamonds in micro pave\n  setting and in 18k white gold . It can be customized in any gold color and\n  purity. It is also available in SI and VS clarity diamonds.&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', 'Brown Diamond and Gold Hoop Earrings', '', ''),
(463, 1, 'Brown Diamonds Inside Out Round Hoops', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;text-align: justify; width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;mso-height-source:userset;height:75.0pt&quot;&gt;\n  &lt;td height=&quot;100&quot; class=&quot;xl65&quot; width=&quot;338&quot; style=&quot;height:75.0pt;width:254pt&quot;&gt;This\n  chic round pair of hoops with inside-out brown diamonds in micro pave setting is a perfect accessory for a classy look. It can be customized in all metal colors and gold purity.&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', 'Brown Diamonds Inside Out Round Hoops', '', ''),
(465, 1, 'Shimmering Diamond and Gold Hoops', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;text-align: justify; width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;mso-height-source:userset;height:75.0pt&quot;&gt;\n  &lt;td height=&quot;100&quot; class=&quot;xl65&quot; width=&quot;338&quot; style=&quot;height:75.0pt;width:254pt&quot;&gt;Pair of\n  Hoops half covered with round diamonds in micro pave setting has been\n  designed aesthetically. It can be customized in all gold color and 14K metal\n  purity.&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', 'Shimmering Diamond and Gold Hoops', '', ''),
(467, 1, 'Shimmering Brown Diamond Hoops', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;text-align: justify; width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;mso-height-source:userset;height:75.0pt&quot;&gt;\n  &lt;td height=&quot;100&quot; class=&quot;xl65&quot; width=&quot;338&quot; style=&quot;height:75.0pt;width:254pt&quot;&gt;Stylish\n  yet simple! This pair of 18K rose gold hoops half covered with fine brown\n  diamonds is a true masterpiece for all jewel lovers. It can be customized in\n  all metal colors and 14K gold purity.&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', 'Shimmering Brown Diamond Hoops', '', ''),
(468, 1, 'Fashion Diamond and Gold Hoops', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;text-align: justify; width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;mso-height-source:userset;height:75.0pt&quot;&gt;\n  &lt;td height=&quot;100&quot; class=&quot;xl65&quot; width=&quot;338&quot; style=&quot;height:75.0pt;width:254pt&quot;&gt;Pair\n  of&amp;nbsp; stylish hoops fully covered with&amp;nbsp; single cut diamonds in micro\n  pave setting have been designed in18K gold. It can be made available in\n  all gold colors and purity.&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', 'Fashion Diamond and Gold Hoops', '', ''),
(470, 1, 'Chic Brown Diamond and Gold Hoops', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;text-align: justify; width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;mso-height-source:userset;height:75.0pt&quot;&gt;\n  &lt;td height=&quot;100&quot; class=&quot;xl65&quot; width=&quot;338&quot; style=&quot;height:75.0pt;width:254pt&quot;&gt;This\n  pair of hoops fully covered with brown diamonds in micro pave setting have\n  been designed in 18k yellow gold. They can be made available in any metal\n  color and 14k gold purity.&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', 'Chic Brown Diamond and Gold Hoops', '', ''),
(471, 1, 'Diamond and Gold Hoop Earrings', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;text-align: justify; width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;mso-height-source:userset;height:75.0pt&quot;&gt;\n  &lt;td height=&quot;100&quot; class=&quot;xl65&quot; width=&quot;338&quot; style=&quot;height:75.0pt;width:254pt&quot;&gt;This\n  pair of hoop earrings designed in 18K gold with fine diamonds in micro\n  pave settings is meant to enhance one\'s looks. It can also be customized in\n  14K gold purity.&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', 'Diamond and Gold Hoop Earrings', '', ''),
(474, 1, 'Brown Diamond and Gold Hoop Earrings', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;text-align: justify; width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;mso-height-source:userset;height:75.0pt&quot;&gt;\n  &lt;td height=&quot;100&quot; class=&quot;xl65&quot; width=&quot;338&quot; style=&quot;height:75.0pt;width:254pt&quot;&gt;This\n  pair of hoop earrings designed in 18K gold semi covered with brown\n  diamonds in micro pave settings is meant to enhance one\'s looks. It can also\n  be customized in 14K gold purity.&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', 'Brown Diamond and Gold Hoop Earrings', '', ''),
(475, 1, 'Diamond and Gold Hoop Earrings', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;text-align: justify; width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;mso-height-source:userset;height:75.0pt&quot;&gt;\n  &lt;td height=&quot;100&quot; class=&quot;xl65&quot; width=&quot;338&quot; style=&quot;height:75.0pt;width:254pt&quot;&gt;This\n  pair of hoop earrings designed in 18K gold with fine diamonds in micro\n  pave settings is meant to enhance one\'s looks. It can also be customized in\n  14K gold purity.&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', 'Diamond and Gold Hoop Earrings', '', ''),
(477, 1, 'Brown Diamond and Gold Hoop Earrings', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;text-align: justify; width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;mso-height-source:userset;height:75.0pt&quot;&gt;\n  &lt;td height=&quot;100&quot; class=&quot;xl65&quot; width=&quot;338&quot; style=&quot;height:75.0pt;width:254pt&quot;&gt;An 18K Rose gold hoop earrings covered with brown diamonds in micro pave settings is\n  classic. It can also be customized in all gold colors and purity.&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', 'Brown Diamond and Gold Hoop Earrings', '', ''),
(478, 1, 'Classic Diamond Hoop Earrings', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;text-align: justify; width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;mso-height-source:userset;height:75.0pt&quot;&gt;\n  &lt;td height=&quot;100&quot; class=&quot;xl65&quot; width=&quot;338&quot; style=&quot;height:75.0pt;width:254pt&quot;&gt;This\n  classic white gold hoop earrings is semi covered with white single cut\n  diamonds in VS clarity. It can also be customized in all metal colors and\n  gold purity.&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', 'Classic Diamond Hoop Earrings', '', ''),
(481, 1, 'Brown Diamond and Gold Hoop Earrings', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;text-align: justify; width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;mso-height-source:userset;height:75.0pt&quot;&gt;\n  &lt;td height=&quot;100&quot; class=&quot;xl65&quot; width=&quot;338&quot; style=&quot;height:75.0pt;width:254pt&quot;&gt;This\n  dainty yellow gold hoop earrings is semi covered with single cut brown\n  diamonds. It can also be customized in 14k gold purity.&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', 'Brown Diamond and Gold Hoop Earrings', '', ''),
(482, 1, 'Pretty Diamond and Gold Hoops', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;text-align: justify; width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;mso-height-source:userset;height:75.0pt&quot;&gt;\n  &lt;td height=&quot;100&quot; class=&quot;xl65&quot; width=&quot;338&quot; style=&quot;height:75.0pt;width:254pt&quot;&gt;This\n  classic pair of white gold hoops, with opulence inside and out, is covered\n  with VS clarity diamonds in single cut. It can also be customized in all gold\n  colors and purity.&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', 'Pretty Diamond and Gold Hoops', '', ''),
(484, 1, 'Brown Diamond and Gold Hoops', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;text-align: justify; width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;mso-height-source:userset;height:75.0pt&quot;&gt;\n  &lt;td height=&quot;100&quot; class=&quot;xl65&quot; width=&quot;338&quot; style=&quot;height:75.0pt;width:254pt&quot;&gt;These\n  dazzling diamond hoops feature single cut natural diamond in micro pave\n  setting in 18k gold. They can be customized in all gold colors and\n  purity.&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', 'Brown Diamond and Gold Hoops', '', ''),
(485, 1, 'White Diamond and Gold Hoop Earrings', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;text-align: justify; width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;mso-height-source:userset;height:75.0pt&quot;&gt;\n  &lt;td height=&quot;100&quot; class=&quot;xl65&quot; width=&quot;338&quot; style=&quot;height:75.0pt;width:254pt&quot;&gt;The\n  timeless hoops in 18k&amp;nbsp; gold bring\n  double the shine with diamond in single cut studded inside out in pave\n  setting. These hoops can be customized in all gold colors and purity.&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', 'White Diamond and Gold Hoop Earrings', '', ''),
(487, 1, 'Diamond and Gold Hoop Earrings', '&lt;table border=&quot;0&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; width=&quot;338&quot; style=&quot;text-align: justify; width: 254pt;&quot;&gt;&lt;tbody&gt;&lt;tr height=&quot;100&quot; style=&quot;mso-height-source:userset;height:75.0pt&quot;&gt;\n  &lt;td height=&quot;100&quot; class=&quot;xl65&quot; width=&quot;338&quot; style=&quot;height:75.0pt;width:254pt&quot;&gt;With\n  opulence inside and out, this pair of 18k gold hoop earrings, is studded\n  with single cut diamonds in micro pave setting. It can also be customized in\n  all gold colors and purity.&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;', '', 'Diamond and Gold Hoop Earrings', '', ''),
